TLM.f("Sancti/07-11",{"officium":"S. Pii I Papæ et Martyris","rule":["OPapaM=Pium;","vide C4b;","Gloria"],"ruleInherited":["Prefatio=Apostolis"],"fallback":"Commune/C4b","from":{"Introitus":"Commune/C4b","Lectio":"Commune/C4b","Graduale":"Commune/C4b","GradualeP":"Commune/C4b","Tractus":"Commune/C4b","Evangelium":"Commune/C4b","Offertorium":"Commune/C4b","Communio":"Commune/C4b"},"sections":{"Introitus":[{"k":"ref","la":"Joann 21:15-17"},{"k":"text","la":"Si díligis me, Simon Petre, pasce agnos meos, pasce oves meas. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 29:2"},{"k":"text","la":"Exaltábo te, Dómine, quóniam suscepísti me, nec delectásti inimícos meos super me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Si díligis me, Simon Petre, pasce agnos meos, pasce oves meas. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Gregem tuum, Pastor ætérne, placátus inténde: et, per beátum Pium Mártyrem tuum atque Summum Pontíficem, perpétua protectióne custódi; quem totíus Ecclésiæ præstitísti esse pastórem."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Petri Apóstoli"},{"k":"ref","la":"1 Pet 5:1-4; 5:10-11"},{"k":"text","la":"Caríssimi: Senióres, qui in vobis sunt, obsécro consénior et testis Christi passiónum, qui et ejus, quæ in futúro revelánda est, glóriæ communicátor: páscite qui in vobis est gregem Dei, providéntes non coácte, sed spontánee secúndum Deum, neque turpis lucri grátia, sed voluntárie; neque ut dominántes in cleris, sed forma facti gregis ex ánimo. Et, cum apparúerit princeps pastórum, percipiétis immarcescíbilem glóriæ corónam. Deus autem omnis grátiæ, qui vocávit nos in ætérnam suam glóriam in Christo Jesu, módicum passos ipse perfíciet, confirmábit solidabítque. Ipsi glória et impérium in sǽcula sæculórum. Amen."}],"Graduale":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus, et mirabília ejus fíliis hóminum.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}],"Tractus":[{"k":"ref","la":"Ps 106:32; 106:31"},{"k":"text","la":"Exáltent eum in Ecclésia plebis: et in cáthedra seniórum laudent eum."},{"k":"text","la":"Confiteántur Dómino misericórdiæ ejus; et mirabília ejus fíliis hóminum","mark":"V"},{"k":"ref","la":"Ps 39:10-11"},{"k":"text","la":"Annuntiávi justítiam tuam in ecclésia magna, ecce, lábia mea non prohibébo: Dómine, tu scisti."},{"k":"text","la":"Justítiam tuam non abscóndi in corde meo: veritátem tuam et salutáre tuum dixi.","mark":"V"},{"k":"text","la":"Non abscóndi misericórdiam tuam, et veritátem tuam a concílio multo.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 16:13-19"},{"k":"text","la":"In illo témpore: Venit Jesus in partes Cæsaréæ Philíppi, et interrogábat discípulos suos, dicens: Quem dicunt hómines esse Fílium hóminis? At illi dixérunt: Alii Joánnem Baptístam, alii autem Elíam, álii vero Jeremíam, aut unum ex prophétis. Dicit illis Jesus: Vos autem quem me esse dícitis? Respóndens Simon Petrus, dixit: Tu es Christus, Fílius Dei vivi. Respóndens autem Jesus, dixit ei: Beátus es, Simon Bar Jona: quia caro et sanguis non revelávit tibi, sed Pater meus, qui in cœlis est. Et ego dico tibi, quia tu es Petrus, et super hanc petram ædificábo Ecclésiam meam, et portæ ínferi non prævalébunt advérsus eam. Et tibi dabo claves regni cœlórum. Et quodcúmque ligáveris super terram, erit ligátum et in cœlis: et quodcúmque sólveris super terram, erit solútum et in cœlis."}],"Offertorium":[{"k":"ref","la":"Jer 1:9-10"},{"k":"text","la":"Ecce, dedi verba mea in ore tuo: ecce, constítui te super gentes et super regna, ut evéllas et déstruas, et ædífices et plantes. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Oblátis munéribus, quǽsumus, Dómine, Ecclésiam tuam benígnus illúmina: ut, et gregis tui profíciat ubíque succéssus, et grati fiant nómini tuo, te gubernánte, pastóres."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Refectióne sancta enutrítam gubérna, quǽsumus, Dómine, tuam placátus Ecclésiam: ut, poténti moderatióne dirécta, et increménta libertátis accípiat et in religiónis integritáte persístat."},{"k":"macro","name":"Per Dominum"}]},"hr":{"ef9ed010c0b24fc9":{"t":"<i>Pomolimo se</i>.\nVječni Pastiru, milosno pazi svoje stado i čuvaj vječnom zaštitom po zagovoru blaženoga Pija, tvoga mučenika i pape koga si postavio za pastira čitave Crkve.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"465033a1b349c3e4":{"t":"Po prikaznim darovima, molimo, Gospodine, dobrostivo rasvijetli svoju Crkvu da i stado tvoje sve više i više napreduje i da ti ugode pastiri koje si postavio.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"48b397156b3ff99b":{"t":"<i>Pomolimo se</i>.\nVladaj, molimo, Gospodine, svojom Crkvom koja je nahranjena, na svetoj gozbi, da po tvome snažnom ravnanju zadobije porast slobode i ustraje u savršenom bogoštovlju.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."}},"variants":{"paschal":{"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Matt 16:18"},{"k":"text","la":"Tu es Petrus, et super hanc petram ædificábo Ecclésiam meam. Allelúja."},{"k":"ref","la":"Ps 44:17-18"},{"k":"text","la":"Constítues eos príncipes super omnem terram: mémores erunt nóminis tui, Dómine. Allelúja."}]}}});
